foreach($version in @('old','new')){$overrides=@{};$defines='RESIDENT_STATE';if($version -eq 'old'){$overrides=$frozen;$defines=''};$cases=@('state');if(!$TargetedOnly){$cases+='growth'};foreach($case in $cases){$dir=Join-Path $out ($version+'/'+$case);New-Item -ItemType Directory -Path $dir -Force|Out-Null;$entry=Join-Path $PSScriptRoot $(if($case -eq 'state'){'Diagnostics/CityResidentStateChecks.cs'}else{'Diagnostics/CityGrowthCandidateChecks.cs'});if($version -eq 'new' -and $case -eq 'growth'){
 $body=[IO.File]::ReadAllText((Join-Path $root 'Assets/Scripts/Runtime/Simulation/Industry/CityCoreIndustrySession.cs'));if(([regex]::Matches($body,'Entities.Simulation=Simulation;')).Count -ne 1){throw 'Session observer anchor changed'}
 $body=[regex]::Replace($body,'(public sealed class CityCoreIndustrySession\s*\{)','$1 internal static long DiagnosticStateNotices;');$body=$body.Replace('Entities.Simulation=Simulation;','Entities.Simulation=Simulation;Entities.ResidentStateChanged+=(m,r)=>{DiagnosticStateNotices++;if(!ReferenceEquals(Entities.Member(m.Person.id),m))throw new InvalidOperationException("Stale diagnostic state member");};');$session=Join-Path $dir 'ObservedSession.cs';[IO.File]::WriteAllText($session,$body);$overrides=@{'CityCoreIndustrySession.cs'=$session}
 $body=[IO.File]::ReadAllText($entry);$anchor='File.WriteAllLines(Path.Combine(args[1],"states.csv"),rows);';if(!$body.Contains($anchor)){throw 'Growth output anchor changed'};$body=$body.Replace($anchor,$anchor+'Console.WriteLine("actualStateNotices="+CityCoreIndustrySession.DiagnosticStateNotices);');$entry=Join-Path $dir 'ObservedGrowth.cs';[IO.File]::WriteAllText($entry,$body)
}
$binary=Build-CityDotNetHost -ProjectRoot $root -OutputDirectory $dir -Entry $entry -Defines $defines -SourceOverrides $overrides;if($case -eq 'state'){& dotnet $binary $dir}else{& dotnet $binary $save $dir};if($LASTEXITCODE -ne 0){throw ($version+' '+$case+' failed')}}}
foreach($relative in @('state/states.csv','state/requests.csv','state/existing-order-defect.csv')){if([IO.File]::ReadAllText((Join-Path $out ('old/'+$relative))) -cne [IO.File]::ReadAllText((Join-Path $out ('new/'+$relative)))){throw ('Baseline differs: '+$relative)}}
if((Get-FileHash -LiteralPath (Join-Path $out 'old/state/final.hcity')).Hash -ne (Get-FileHash -LiteralPath (Join-Path $out 'new/state/final.hcity')).Hash){throw 'Saved wire differs'}
if(!$TargetedOnly -and [IO.File]::ReadAllText((Join-Path $out 'old/growth/states.csv')) -cne [IO.File]::ReadAllText((Join-Path $out 'new/growth/states.csv'))){throw 'Growth/30k state differs'}
Write-Output 'PASS notification equivalence to frozen934e064; see separate baseline ordering defect, not a general cold-equivalence claim'

if(!$TargetedOnly){$dir=Join-Path $out 'maintenance';New-Item -ItemType Directory -Path $dir|Out-Null;& dotnet (Join-Path $out 'new/state/bin/Release/net10.0/CityModelHost.dll') $dir $save;if($LASTEXITCODE -ne 0){throw 'State maintenance count/cost failed'}}
